class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # Use dynamic programming with state: (zeros_remaining, ones_remaining, last_element, consecutive_count)
        # We'll use memoization
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(zeros, ones, last, consecutive):
            # last: 0 or 1, consecutive: number of consecutive identical elements at end
            if zeros == 0 and ones == 0:
                return 1

            result = 0

            # Try to place a zero
            if zeros > 0:
                if last == 0:
                    # Adding another zero - check limit
                    if consecutive < limit:
                        result = (result + dp(zeros - 1, ones, 0, consecutive + 1)) % MOD
                else:
                    # Adding zero after a one - starts a new sequence of zeros
                    result = (result + dp(zeros - 1, ones, 0, 1)) % MOD

            # Try to place a one
            if ones > 0:
                if last == 1:
                    # Adding another one - check limit
                    if consecutive < limit:
                        result = (result + dp(zeros, ones - 1, 1, consecutive + 1)) % MOD
                else:
                    # Adding one after a zero - starts a new sequence of ones
                    result = (result + dp(zeros, ones - 1, 1, 1)) % MOD

            return result

        # Base case: we can start with either 0 or 1
        # If both zero and one are available, we start with either
        # If only zero, start with 0
        # If only one, start with 1

        if zero == 0 and one == 0:
            return 1
        elif zero == 0:
            return dp(0, one - 1, 1, 1)
        elif one == 0:
            return dp(zero - 1, 0, 0, 1)
        else:
            # Both available, start with either 0 or 1
            return (dp(zero - 1, one - 1, 0, 1) + dp(zero - 1, one - 1, 1, 1)) % MOD

