        if one >= 1:
            dp[0][1][1][1] = 1

        # Fill the DP table
        for z in range(zero + 1):
            for o in range(one + 1):
                for last in range(2):
                    for length in range(1, limit + 1):
                        if z > zero or o > one:
                            continue

                        if z == zero and o == one:
                            continue  # Already counted in result

                        # Try to place a zero
                        if z < zero:
                            if last == 0:
                                if length < limit:
                                    dp[z + 1][o][0][length + 1] = (dp[z + 1][o][0][length + 1] + dp[z][o][last][length]) % MOD
                            else:
                                dp[z + 1][o][0][1] = (dp[z + 1][o][0][1] + dp[z][o][last][length]) % MOD

                        # Try to place a one
                        if o < one:
                            if last == 1:
                                if length < limit:
                                    dp[z][o + 1][1][length + 1] = (dp[z][o + 1][1][length + 1] + dp[z][o][last][length]) % MOD
                            else:
                                dp[z][o + 1][1][1] = (dp[z][o + 1][1][1] + dp[z][o][last][length]) % MOD

        # Sum all valid final states
        result = 0
        for last in range(2):
            for length in range(1, limit + 1):
                result = (result + dp[zero][one][last][length]) % MOD

        return result

class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # Create a 4D DP array: dp[z][o][last][length]
        # z: number of zeros used (0 to zero)
        # o: number of ones used (0 to one) 
        # last: last digit (0 or 1)
        # length: consecutive length of the last digit (1 to limit)

        # Initialize 4D array with zeros
        dp = [[[[0 for _ in range(limit + 1)] for _ in range(one + 1)] for _ in range(zero + 1)] for _ in range(2)]

        # Initialize base cases - we can start with either 0 or 1
        # Starting with a 0: 1 zero used, 0 ones used
        if zero >= 1:
            dp[0][1][0][1] = 1

        # Starting with a 1: 0 zeros used, 1 one used
        if one >= 1:
            dp[0][1][1][1] = 1

        # Fill the DP table for all states
        for z in range(zero + 1):
            for o in range(one + 1):
                for last in range(2):
                    for length in range(1, limit + 1):
                        # Skip states that are not reachable or invalid
                        if z > zero or o > one:
                            continue

                        # Skip the final state (we'll sum at the end)
                        if z == zero and o == one:
                            continue

                        # Try to add a zero
                        if z < zero:
                            if last == 0:
                                # Can extend current run of zeros if it's less than limit
                                if length < limit:
                                    dp[z + 1][o][0][length + 1] = (dp[z + 1][o][0][length + 1] + dp[z][o][last][length]) % MOD
                            else:
                                # Start a new run of zeros
                                dp[z + 1][o][0][1] = (dp[z + 1][o][0][1] + dp[z][o][last][length]) % MOD

                        # Try to add a one
                        if o < one:
                            if last == 1:
                                # Can extend current run of ones if it's less than limit
                                if length < limit:
                                    dp[z][o + 1][1][length + 1] = (dp[z][o + 1][1][length + 1] + dp[z][o][last][length]) % MOD
                            else:
                                # Start a new run of ones
                                dp[z][o + 1][1][1] = (dp[z][o + 1][1][1] + dp[z][o][last][length]) % MOD

        # Sum all valid final states (when we've used exactly zero zeros and one ones)
        result = 0
        for last in range(2):
            for length in range(1, limit + 1):
                result = (result + dp[zero][one][last][length]) % MOD

        return result

class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        # Count frequency of each element
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Find maximum frequency
        max_freq = max(freq.values())

        # Check if any element appears more than half the array length
        # If max_freq > len(nums) // 2, it's impossible to split
        return max_freq <= len(nums) // 2

class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        # Count frequency of each element
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Check if any element appears more than 2 times
        # Since we have 2 parts, each can hold at most 1 copy of any element
        # So maximum frequency of any element should be at most 2
        for count in freq.values():
            if count > 2:
                return False

        return True

