class Solution:
    def countTestedDevices(self, batteryPercentages: List[int]) -> int:
        tested_count = 0

        for i in range(len(batteryPercentages)):
            # If current device has positive battery percentage after accounting for previous tests
            if batteryPercentages[i] > tested_count:
                tested_count += 1

        return tested_count

class Solution:
    def countTestedDevices(self, batteryPercentages: List[int]) -> int:
        tested_count = 0

        for i in range(len(batteryPercentages)):
            # If current device's battery percentage is greater than the number of tests that have been done so far
            # then this device will be tested
            if batteryPercentages[i] > tested_count:
                tested_count += 1

        return tested_count

class Solution:
    def countTestedDevices(self, batteryPercentages: List[int]) -> int:
        tested_count = 0

        for i in range(len(batteryPercentages)):
            # If original battery percentage is greater than the number of tests so far
            if batteryPercentages[i] > tested_count:
                tested_count += 1
                # Reduce battery of all subsequent devices by 1 (but not below 0)
                for j in range(i + 1, len(batteryPercentages)):
                    batteryPercentages[j] = max(0, batteryPercentages[j] - 1)

        return tested_count

